        [3] = {name = "HOSTILE_SECOND_AGGRO", tooltip = "The unit that is second highest on the current threatlist of the creature", params = {{name = "Max Range", tooltip = "0: unlimited"}, {name = "Player Only", tooltip = "(0/1)"}, {name = "Power Type", tooltip = "Power Types: 1 - MANA. 2 - RAGE. 3 - FOCUS. 4 - ENERGY"}, {name = "Aura", tooltip = "only target units without this aura"}}, core = "Second highest aggro, maxdist, playerOnly, powerType + 1"},
